def all_posts():
    # Newest first for the listing page; POSTS itself stays chronological.
    return sorted(POSTS, key=lambda post: post["date"], reverse=True)


def get_post(slug):
    for post in POSTS:
        if post["slug"] == slug:
            return post
    return None
